@import "../../../styles/responsive.scss";

.overall_add_policy_receipts_container {
  padding: 1.5rem;

  @include tablet-sm {
    padding: 1rem;
  }

  @include mobile-sm {
    padding: 0.75rem;
  }

  .label_header {
    color: #111927;
    font-family: "Inter", sans-serif;
    font-size: 30px;
    font-weight: 600;
    margin-left: 10px;

    @include tablet-sm {
      font-size: 1.5rem;
      text-align: center;
      margin-left: 0;
    }

    @include mobile-sm {
      font-size: 1.25rem;
    }
  }
  .calender__container {
    border-radius: 30px;
    background-color: #fff !important;
    margin-top: 10px;
  }
  .p-calendar {
    position: relative;
    display: inline-flex;
    width: 100%;
  }
  .calenderlable__container {
    color: #000;
    margin-bottom: 8px;
    font-family: "Inter", sans-serif;
    font-size: 16px;

    font-weight: 500;
  }
  .p-card {
    background: #ffffff;
    color: #4b5563;

    border-radius: 6px;
    box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1) !important;
  }
  .p-calendar .p-inputtext {
    flex: 1 1 auto;
    width: 1%;
    border-right-style: hidden;
    border-top-left-radius: 10px;
    border-bottom-left-radius: 10px;
    border-color: #d1d5db;
  }
  .p-button.p-button-icon-only {
    width: 3rem;
    padding: 0.75rem 0;
    color: #6366f1;
    background: #fff;
    border-left-style: hidden;
    border-color: #d1d5db;
    border-top-right-radius: 10px;
    border-bottom-right-radius: 10px;
    cursor: pointer;
  }
  .p-breadcrumb {
    border: 1px solid #fff !important;
    border-radius: 6px;
    padding: 1rem 0rem;
  }
  .exit_print_buttons {
    display: flex;
    justify-content: space-between;
  }
  .p-breadcrumb .p-breadcrumb-list li:last-child .p-menuitem-text {
    color: #b1b1b1;
  }

  .custom-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 1rem;
    z-index: 1;
  }

  .custom-modal {
    background-color: #fff;
    overflow-y: auto;
    position: relative;
    width: 22%;
    border-radius: 20px;
    height: 180px;
    display: grid;
    justify-content: center;
    align-items: center;
    padding: 10px;
  }

  .popup__icon {
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .popup__text {
    color: #111927;
    text-align: center;
    font-size: 20px;
    font-weight: 500;
    font-family: "Inter", sans-serif;
  }

  .modal-header {
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 20px;
    font-family: "Inter", sans-serif;
  }

  .modal-body {
    color: #fff;
  }
  .print.p-button {
    color: #ffffff;
    background: #6366f1;
    border: 1px solid #6366f1;
    padding: 0.75rem 1.25rem;
    font-size: 16px;
    transition: background-color 0.2s, color 0.2s, border-color 0.2s,
      box-shadow 0.2s;
    border-radius: 30px;
    margin-right: 10px;
    width: 100px;
    height: 36px;
  }

  .label_payment {
    color: #111927;
    font-family: "Inter", sans-serif;
    font-size: 20px;
    font-style: normal;
    font-weight: 500;
    line-height: normal;
    margin-top: 50px;
    margin-bottom: 20px;
  }

  .inputrows__container {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    margin-right: -0.5rem;
    margin-left: -0.5rem;
    margin-top: -0.5rem;
    background-color: antiquewhite;
  }
  .field__container {
    width: 100%;
    height: 44px;
    margin-top: 10px;
    overflow: hidden;
    text-wrap: nowrap;
    border-radius: 12px;
  }

  .lg-col-2-5 {
    flex: 0 0 20%;
    max-width: 20%;
  }
  .submit_button {
    width: 173px;
    height: 50px;
    border-radius: 30px;
    background: #6366f1;
    font-size: 18px;
    font-weight: 500;
  }
  .next_container {
    display: flex;
    justify-content: flex-end;
    align-items: flex-end;
    margin-top: 50px;

    @include tablet-sm {
      justify-content: center;
      margin-top: 2rem;
    }

    @include mobile-sm {
      margin-top: 1.5rem;
    }
  }
  .dropdown__container {
    width: 100%;
    height: 44px;
    border-radius: 12px;
    overflow: hidden;
    text-wrap: nowrap;
    margin: 10px 0px;
  }
}
@media (min-width: 576px) {
  .md-col-6 {
    flex: 0 0 50%;
    max-width: 50%;
  }
}

/* Responsive Grid Layout */
@include tablet-sm {
  .grid {
    .col-3,
    .col-6,
    .sm-col-12 {
      width: 100% !important;
      margin-bottom: 1rem;
    }

    .col-offset-9 {
      margin-left: 0 !important;
    }
  }
}

@include mobile-sm {
  .grid {
    .col-3,
    .col-6,
    .sm-col-12 {
      width: 100% !important;
      margin-bottom: 0.75rem;
    }

    .col-offset-9 {
      margin-left: 0 !important;
    }
  }

  .field__container,
  .dropdown__container {
    margin-top: 8px;
  }

  .calenderlable__container {
    font-size: 14px;
  }
}
